begin;
create table if not exists academics.grading_scales(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,name text not null,min_score numeric(6,2) not null,max_score numeric(6,2) not null,grade text not null,remark text not null default '',points numeric(5,2),active boolean not null default true,check(min_score<=max_score));
create table if not exists academics.assessment_schemes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,name text not null,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists academics.assessment_components(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,scheme_id uuid not null references academics.assessment_schemes(id) on delete cascade,name text not null,weight numeric(5,2) not null check(weight>=0 and weight<=100),sequence smallint not null default 1);
create table if not exists academics.attendance_registers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,class_id uuid not null references academics.classes(id),term_id uuid not null references academics.terms(id),attendance_date date not null,status text not null default 'open',created_by uuid references authn.users(id),created_at timestamptz not null default now(),unique(tenant_id,class_id,attendance_date));
create table if not exists academics.attendance_entries(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,register_id uuid not null references academics.attendance_registers(id) on delete cascade,student_id uuid not null references app.students(id),attendance_date date not null,status text not null check(status in('present','absent','late','excused')),note text not null default '',recorded_by uuid references authn.users(id),unique(register_id,student_id));
create table if not exists academics.score_entries(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),class_id uuid not null references academics.classes(id),subject_id uuid not null references academics.subjects(id),term_id uuid not null references academics.terms(id),component_id uuid references academics.assessment_components(id),score numeric(7,2) not null,recorded_by uuid references authn.users(id),updated_at timestamptz not null default now(),unique(tenant_id,student_id,subject_id,term_id,component_id));
create table if not exists academics.student_reports(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),term_id uuid not null references academics.terms(id),class_id uuid not null references academics.classes(id),status text not null default 'draft' check(status in('draft','submitted','class_reviewed','approved','published','returned','withdrawn')),version integer not null default 1,overall_total numeric(9,2),overall_average numeric(7,2),position integer,teacher_comment text not null default '',principal_comment text not null default '',published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,student_id,term_id));
create table if not exists academics.subject_results(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,report_id uuid not null references academics.student_reports(id) on delete cascade,subject_id uuid not null references academics.subjects(id),total_score numeric(7,2),grade text,remark text,position integer,unique(report_id,subject_id));
create table if not exists academics.report_workflow_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,report_id uuid not null references academics.student_reports(id) on delete cascade,from_status text,to_status text not null,comment text not null default '',actor_id uuid references authn.users(id),created_at timestamptz not null default now());
create table if not exists academics.transcript_issuances(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),verification_token text not null unique,status text not null default 'issued',pdf_object_key text,issued_by uuid references authn.users(id),issued_at timestamptz not null default now());
create table if not exists academics.certificates(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid references app.students(id),staff_id uuid references app.staff(id),certificate_type text not null,verification_token text not null unique,pdf_object_key text,status text not null default 'issued',issued_at timestamptz not null default now());
insert into app.schema_migrations(version) values ('0004_academics_reporting') on conflict do nothing;
commit;
